PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS administrators (id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS assessments (id INTEGER PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', academic_year TEXT NOT NULL DEFAULT 'ALL' CHECK(academic_year IN('FY','SY','TY','ALL')), duration_minutes INTEGER NOT NULL DEFAULT 30 CHECK(duration_minutes>0), passing_percentage REAL NOT NULL DEFAULT 60 CHECK(passing_percentage BETWEEN 0 AND 100), max_attempts INTEGER NOT NULL DEFAULT 1 CHECK(max_attempts>0), enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN(0,1)), auto_submit_tab_switch INTEGER NOT NULL DEFAULT 1, auto_submit_fullscreen_exit INTEGER NOT NULL DEFAULT 1, maximum_warnings INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')), updated_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY, assessment_id INTEGER NOT NULL REFERENCES assessments(id) ON DELETE CASCADE, question_text TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'General', correct_option_id INTEGER, position INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS options (id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE, option_text TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS examination_attempts (id TEXT PRIMARY KEY, assessment_id INTEGER NOT NULL REFERENCES assessments(id), candidate_name TEXT NOT NULL, candidate_email TEXT NOT NULL DEFAULT '', candidate_class TEXT NOT NULL DEFAULT '', candidate_division TEXT NOT NULL DEFAULT '', started_at TEXT NOT NULL, deadline_at TEXT NOT NULL, submitted_at TEXT, status TEXT NOT NULL DEFAULT 'in_progress' CHECK(status IN('in_progress','submitted','expired')), warnings INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_attempt_email_assessment ON examination_attempts(candidate_email, assessment_id);
CREATE INDEX IF NOT EXISTS idx_attempt_status ON examination_attempts(status);
CREATE TABLE IF NOT EXISTS submitted_answers (id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES examination_attempts(id) ON DELETE CASCADE, question_id INTEGER NOT NULL REFERENCES questions(id), option_id INTEGER REFERENCES options(id), updated_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE(attempt_id, question_id));
CREATE TABLE IF NOT EXISTS results (id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL UNIQUE REFERENCES examination_attempts(id), total_questions INTEGER NOT NULL, correct_answers INTEGER NOT NULL, incorrect_answers INTEGER NOT NULL, unanswered INTEGER NOT NULL, score INTEGER NOT NULL, percentage REAL NOT NULL, passed INTEGER NOT NULL CHECK(passed IN(0,1)), completed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS certificates (id INTEGER PRIMARY KEY, certificate_id TEXT NOT NULL UNIQUE, result_id INTEGER NOT NULL UNIQUE REFERENCES results(id), candidate_name TEXT NOT NULL, assessment_title TEXT NOT NULL, score_text TEXT NOT NULL, completion_date TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS violation_logs (id INTEGER PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES examination_attempts(id) ON DELETE CASCADE, violation_type TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (datetime('now')));
